export const getModule=id=>modules.find(m=>m.id===id);
export function getModules(filter='all'){const list=modules.filter(m=>m.phase===filter||m.track===filter);return list.length?list:modules;}
export function getLearningPath(focus='all'){
 if(!['medicine','diving'].includes(focus))return modules;
 const selected=new Set(modules.filter(m=>m.phase===focus||m.phase==='common'||m.phase==='integration').map(m=>m.id));
 const include=id=>{for(const prerequisite of getModule(id).prerequisites){if(!selected.has(prerequisite)){selected.add(prerequisite);include(prerequisite);}}};
 for(const id of [...selected])include(id);
 return modules.filter(m=>selected.has(m.id));
}
